import { html } from "../../../../html.js";
import { marked } from "/prototype/vendor/marked.js";
import { Icon } from "../../ui/index.js";
const stamp=t=>new Date(t).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
const markdown=t=>html`<div class="e-markdown" dangerouslySetInnerHTML=${{__html:marked.parse(t)}}/>`;
export function Event({event,compact=false}){const e=event;const time=e.at&&html`<time>${stamp(e.at)}</time>`;const label=e.type==='agent'?'Durable':e.type==='steer'?'Steer':'You';if(e.type==='date')return html`<div class="e-date">${e.label}</div>`;if(['user','steer','agent'].includes(e.type))return html`<article class=${`e-event e-${e.type}`}>${!compact&&html`<header>${label}${time}</header>`}${markdown(e.text)}${e.type==='agent'&&e.text.includes('```')&&html`<div class="e-code-actions"><span>TypeScript</span><button onClick=${()=>navigator.clipboard?.writeText(e.text.match(/```(?:\w+)?\n([\s\S]*?)```/)?.[1]||'')}>Copy</button></div>`}</article>`;if(e.type==='thinking')return html`<details class="e-event e-thinking"><summary><${Icon} name="brain"/> Reasoning ${time}</summary><p>${e.text}</p></details>`;if(e.type==='tools')return html`<details class="e-event e-tools"><summary><${Icon} name="terminal"/> Worked for 3m 43s · ${e.items.length} tool calls ${time}</summary>${e.items.map(x=>html`<div class="e-tool"><b>${x.status==='running'?'◌':'✓'} ${x.name}</b><code>${x.arg}</code><span>${x.status}</span><pre>${x.output}</pre></div>`)}</details>`;if(e.type==='diff')return html`<section class="e-event e-diffcard"><b>Changed files</b><span>${e.files}</span><em>+${e.plus} −${e.minus}</em><button>Open diff</button></section>`;if(e.type==='tests')return html`<section class="e-event e-tests"><${Icon} name="circle-check"/><b>Focused tests</b><span>${e.passed} passed · ${e.failed} failed</span></section>`;if(e.type==='subagent')return html`<section class="e-event e-subagent"><${Icon} name="bot"/><span><b>${e.role} ${e.status}</b><small>${e.text}</small></span><a href=${`#${e.child}`}>Open child ↗</a></section>`;if(e.type==='approval')return html`<section class="e-event e-approval"><${Icon} name="shield-check"/><span><b>Approval gate · PR #${e.pr}</b><small>${e.sha} · CI ${e.ci} · ${e.verdict}</small></span><button>Sign with passkey</button></section>`;if(e.type==='budget')return html`<section class="e-event e-budget">⚠ ${e.text}</section>`;if(e.type==='notice'||e.type==='queued')return html`<section class=${`e-event e-notice ${e.type}`}>${e.type==='queued'?'◷':'ⓘ'} ${e.text}${time}</section>`;if(e.type==='attachment')return html`<section class="e-event e-attachment"><div>▧</div><span><b>${e.name}</b><small>${e.text}</small></span></section>`;if(e.type==='citation')return html`<a class="e-event e-citation" href="https://example.test">${e.text}</a>`;if(e.type==='stream')return html`<section class="e-event e-stream">${e.text}<i></i></section>`;return null}
export function Events({events,className}){return html`<div class=${className}>${events.map((event,i)=>html`<${Event} key=${i} event=${event}/>`)} </div>`}
